Object.assign(window.deepArticles, {
  "corporate-politics-geacps": geacpsCorporateArticle({
    title:"Corporate Politics in the Greater East Asian Co-Prosperity Sphere",category:"Political systems",eyebrow:"Associated states · corporate houses · 1970–2000",infoboxKicker:"Mature imperial political economy",
    flag:{src:"assets/diagrams/corporate-politics-geacps.svg",alt:"Diagram showing Tokyo, Japanese corporate houses, associated governments, and local political networks",caption:"Japanese primacy is implemented through legally distinct states and indispensable corporate systems"},
    lead:"Corporate politics in the Greater East Asian Co-Prosperity Sphere describes the development of Japanese firms from postwar concession operators into indispensable political institutions across associated states. The corporations do not replace sovereignty. They make effective government, infrastructure, credit, technical careers, and electoral organization increasingly difficult to sustain without corporate consent.",
    canon:"The corporate-host bargain, 1970s jurisdictional challenges, preservation of Japanese ownership, transition from self-defense to patronage, structural capture by 2000, and Tokyo's doctrine of mature coordination are established. Complete country-by-country patronage networks, company assignments, scandals, campaign rules, and ministry rosters remain open.",
    sections:[
      {id:"inheritance",title:"The victory inheritance",html:"<p>Japanese corporations enter many territories before their successor governments become sovereign. Banks, railways, mines, shipping, plantations, utilities, and ports are already in Japanese hands when the associated-state system receives its postwar legal form.</p>"},
      {id:"machinery",title:"The operating machinery of primacy",html:"<p>Tokyo defines defense, ownership, technology, and strategic-route limits. Corporate houses implement them through investment, insurance, procurement, management, maintenance, standards, and commercial intelligence. Political hierarchy becomes material without one colonial civil service.</p>"},
      {id:"challenge",title:"The jurisdictional challenge",html:"<p>During the 1970s associated governments demand taxation, national policing, labor regulation, public access, local management, environmental rules, and limits on land privilege. Tokyo increasingly accepts these claims when they do not threaten ownership or strategic continuity.</p>"},
      {id:"weapons",title:"Corporate weapons below open defiance",html:"<p>Firms answer through credit, insurance, investment delay, supplier pressure, patents, technical certification, personnel transfers, maintenance schedules, market access, and the location of new projects. Essential services continue, preserving an appearance of obedience while reform becomes expensive.</p>"},
      {id:"patronage",title:"From defense to patronage",html:"<p>By the late 1980s firms finance civic groups, institutes, scholarships, media, party organizations, campaign services, and development coalitions. The transition is gradual: a company first protects a concession, then favors reliable officials, then builds an entire political environment.</p>"},
      {id:"capture",title:"Structural capture without abolished states",html:"<p>Associated governments retain crowns, cabinets, legislatures, courts, police, citizenship, and flags. Yet a serious party may be unable to fund campaigns, promise growth, place graduates, or maintain infrastructure against the dominant houses. Sovereignty survives; political alternatives narrow.</p>"},
      {id:"tokyo",title:"Tokyo's mature-coordination doctrine",html:"<p>Japanese politicians see functioning systems, local managers, consumer growth, national-language institutions, and governments that continue signing contracts. What foreign critics call capture, Tokyo describes as successful coordination whose occasional abuses require correction.</p>"},
      {id:"culture",title:"The cultural answer",html:"<p><a href='japanese-cyberpunk.html'>Japanese cyberpunk</a> and associated-state political fiction make the hidden machinery visible: the corporation that never issues an illegal order, the minister who freely chooses among options selected for him, and the technically perfect city in which no person can identify who governs.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"corporate-host-bargain.html",kicker:"Constitutional bargain",label:"Corporate–Host Bargain"},{href:"japanese-corporate-patronage.html",kicker:"Political mechanism",label:"Japanese Corporate Patronage"}],
    facts:[["Formation","Postwar corporate concessions"],["Political challenge","1970s onward"],["Patronage transition","Late 1980s"],["Mature form","By 2000"],["Japanese red line","Controlling ownership and strategic continuity"],["Host-state gains","Jurisdiction, taxation, labor, policing, and access"],["Corporate instrument","Credit, systems, standards, and sponsorship"],["Tokyo's description","Mature coordination"]]
  }),

  "corporate-host-bargain": geacpsCorporateArticle({
    title:"Corporate–Host Bargain",category:"Constitutional political economy",eyebrow:"Japanese ownership · associated-state jurisdiction",infoboxKicker:"Operating bargain of the Sphere",
    flag:{src:"assets/diagrams/corporate-host-bargain.svg",alt:"Layer diagram separating Japanese ownership and strategic command from host-state jurisdiction",caption:"Associated governments gain rule within the system; Japanese houses retain command of the economic chain"},
    lead:"The corporate–host bargain is the mature division of authority between Japanese corporate houses and the governments in whose territory they operate. It protects Japanese controlling ownership, finance, technology, and system-wide direction while recognizing local taxation, policing, labor law, language, inspection, and public-service obligations.",
    canon:"The two-layer bargain, principal defended and surrendered privileges, corporate methods of compliance, associated-state jurisdictional gains, and strategic exceptions are established. Exact national statutes, arbitration courts, compensation formulas, and enterprise-specific agreements remain open.",
    sections:[
      {id:"problem",title:"The sovereignty problem",html:"<p>A railway may cross a sovereign country while its finance, signaling, procurement, software, insurance, and engineering remain Japanese. A refinery may employ local citizens under national law while its controlling bank, patents, export contracts, and senior appointments sit abroad.</p>"},
      {id:"ownership",title:"What Japan continues to defend",html:"<p>Tokyo protects controlling shares, compensation against seizure, strategic technology, access to Japanese finance and courts, reliable military logistics, and continuity of essential imperial systems. These are treated as foundations of the settlement, not temporary concessions.</p>"},
      {id:"jurisdiction",title:"What host governments gain",html:"<p>Associated states obtain tax authority, labor and environmental regulation, police access, public use of roads and utilities, local-language education, promotion rules, domestic supplier quotas, operational records, emergency obligations, and restrictions on new land acquisition.</p>"},
      {id:"compliance",title:"Compliance without surrender",html:"<p>Firms issue non-voting local shares, promote regional managers while moving strategy upward, transfer roads while retaining maintenance and dispatch, create national subsidiaries while controlling their credit, and disclose local accounts while group allocation remains in Japan.</p>"},
      {id:"dependency",title:"The detachable machine that cannot be detached",html:"<p>A government can seize a physical plant and discover that it lacks replacement parts, certification, contracts, software, records, insurance, trained engineers, and market access. The corporate asset is a chain of relationships rather than only land and machinery.</p>"},
      {id:"arbitration",title:"Tokyo as interested arbiter",html:"<p>Japan is not neutral: it wants associated governments stable and Japanese property secure. It disciplines obsolete municipal privileges and blatant abuses while blocking confiscation, hostile strategic ownership, and disruptions to defense or continental transport.</p>"},
      {id:"variation",title:"Variation across the Sphere",html:"<p>Thailand's banks and military companies bargain from strength. The Philippines uses constitutional nationalism. Manchukuo confronts Mantetsu inside a dense Japanese industrial system. Smaller archipelago and Mekong states depend more heavily on one or two corporate chains.</p>"},
      {id:"settlement",title:"The mature settlement",html:"<p>The associated state becomes more capable of administering Japanese capital without becoming capable of replacing it. Workers and municipalities gain real protections; national industrial sovereignty remains incomplete.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"associated-state-economic-nationalism.html",kicker:"Host-state doctrine",label:"Associated-State Economic Nationalism"},{href:"japanese-corporate-scandals.html",kicker:"Enforcement",label:"Japanese Corporate Scandals"}],
    facts:[["Parties","Japanese firms and associated governments"],["Core Japanese claim","Controlling ownership"],["Core host claim","Territorial jurisdiction"],["Common host gains","Tax, labor, police, access, and promotion"],["Common corporate reserve","Finance, patents, standards, and strategy"],["Principal arbiter","Government of Japan"],["Mature period","1970s–2000"],["Result","Greater jurisdiction without full economic sovereignty"]]
  }),

  "associated-state-economic-nationalism": geacpsCorporateArticle({
    title:"Associated-State Economic Nationalism",category:"Political doctrines",eyebrow:"GEACPS associates · national jurisdiction · 1970s onward",infoboxKicker:"Reform current within the Sphere",
    flag:{src:"assets/diagrams/corporate-host-bargain.svg",alt:"Diagram of associated-state demands operating beneath retained Japanese control",caption:"Economic nationalists seek jurisdiction, redundancy, and local advancement without necessarily leaving the Sphere"},
    lead:"Associated-state economic nationalism is the family of political programs that seeks national authority over Japanese-owned industry without necessarily rejecting Japanese leadership or attempting wholesale nationalization. Its practical agenda centers on taxation, labor protection, police jurisdiction, public access, local management, technical redundancy, and domestic supplier capacity.",
    canon:"The doctrine's rise in the 1970s, common demands, uneven national forms, limited victories, and inability to displace Japanese finance and technology are established. Party names, intellectual founders, election results, and exact country programs remain open.",
    sections:[
      {id:"origins",title:"Development creates the claimant",html:"<p>Japanese schools, firms, and technical programs produce local engineers, lawyers, managers, and officials who accept the value of the system while rejecting the claim that only expatriates can direct it. Development generates the cadres who demand jurisdiction.</p>"},
      {id:"programme",title:"The common program",html:"<p>Programs call for corporate taxation, national inspection, local promotion, national labor codes, public emergency duties, environmental rules, access to company roads and utilities, limits on land acquisition, supplier quotas, and national copies of essential records.</p>"},
      {id:"limits",title:"Nationalism below rupture",html:"<p>Most governing movements do not demand immediate withdrawal from the Sphere. They know that shipping, credit, standards, strategic protection, and export markets are tied to Japan. Their aim is to make dependency national and negotiable rather than foreign and absolute.</p>"},
      {id:"manchukuo",title:"The Manchukuoan hard case",html:"<p>Manchukuo possesses major industry, a court, trained bureaucracy, and strong national identity, yet Mantetsu and Japanese houses control the chains governing that industry. Its confrontations become the model every other associate studies.</p>"},
      {id:"thailand",title:"Thailand's stronger position",html:"<p>Thai banks, state-connected companies, monarchy, and armed forces prevent complete corporate dependence. Bangkok can demand joint ventures and domestic participation while remaining a principal Japanese partner.</p>"},
      {id:"smaller",title:"The smaller-state problem",html:"<p>In archipelago and Mekong states, a government may depend upon the same corporate group for its port, power, export crop, bank credit, communications, and ruling coalition. Legal sovereignty does not supply leverage when every alternative requires the same gatekeeper.</p>"},
      {id:"victories",title:"Real but bounded victories",html:"<p>By 1985 company districts are more open to national police, local workers advance further, cities collect more revenue, and emergency systems are less fragile. These are material gains even though controlling shares and final investment authority remain Japanese.</p>"},
      {id:"capture",title:"From reformers to clients",html:"<p>Corporate sponsorship later divides the movement. Some reformers accept gradual bargains and enter company-supported institutes or parties; others condemn a system that has learned to finance the vocabulary of nationalism while keeping its economic limits intact.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"corporate-host-bargain.html",kicker:"Operating settlement",label:"Corporate–Host Bargain"},{href:"mantetsu-manchukuo-disputes.html",kicker:"Defining confrontation",label:"Mantetsu–Manchukuo Disputes"}],
    facts:[["Rise","1970s"],["Arena","Associated GEACPS states"],["Immediate aim","National jurisdiction over foreign-owned systems"],["Typical demands","Tax, police, labor, promotion, access, and records"],["Strategic posture","Reform within the Sphere"],["Strongest bargaining state","Thailand"],["Defining hard case","Manchukuo"],["Long-term limit","Japanese control of finance, ownership, and technology"]]
  }),

  "mantetsu-manchukuo-disputes": geacpsCorporateArticle({
    title:"Mantetsu–Manchukuo Disputes",category:"Political-economic conflicts",eyebrow:"Manchukuo · Mantetsu · 1970s–1990s",infoboxKicker:"Recurring corporate-sovereignty conflict",
    flag:{src:"assets/diagrams/mantetsu-manchukuo-disputes.svg",alt:"Escalation loop showing a Manchukuoan reform, narrow Mantetsu compliance, national escalation, and Japanese intervention",caption:"Mantetsu repeatedly makes a token concession, forces visible escalation, and reaches Tokyo as the injured technical operator"},
    lead:"The Mantetsu–Manchukuo disputes were recurring confrontations over taxation, corporate municipalities, promotion, police access, land, records, utilities, and ownership. Mantetsu usually prevailed because it understood Japanese political tolerances better than the Manchukuoan ministries and could make a national sovereignty claim appear to threaten continental operations.",
    canon:"The repeated escalation pattern, core subjects of dispute, Mantetsu's political technique, Tokyo's red lines, limited Manchukuoan gains, and influence on later corporate patronage are established. Individual crisis dates, ministers, arrests, statutes, and settlement instruments remain open.",
    sections:[
      {id:"setting",title:"An industrial state without industrial command",html:"<p>Manchukuo contains steel, chemicals, vehicles, rail equipment, arms, mines, and corporate cities. Yet Mantetsu controls the network joining much of that capacity to capital, standards, procurement, transport, and the wider Japanese market.</p>"},
      {id:"demand",title:"The reasonable national demand",html:"<p>A dispute begins with a defensible measure: municipal tax, promotion quotas, housing inspection, police access, land limits, account disclosure, public utilities, or local voting shares. Tokyo may privately regard the proposal as overdue.</p>"},
      {id:"compliance",title:"Mantetsu's narrow compliance",html:"<p>Mantetsu follows the text while shifting decisive functions elsewhere. It pays tax but reclassifies strategic property, promotes citizens but moves authority to a Japanese office, transfers roads but retains maintenance and freight priority, or issues dividend shares without votes.</p>"},
      {id:"briefing",title:"The technical campaign in Tokyo",html:"<p>The company briefs ministries, banks, services, and newspapers that the reform threatens readiness, freight, investment, concession law, Japanese citizens, or a dangerous imperial precedent. Each claim is narrow enough to sound administratively responsible.</p>"},
      {id:"escalation",title:"Manchukuo crosses the visible line",html:"<p>Frustrated ministers suspend a license, threaten compulsory administration, seize records, arrest an official, block a transfer, or issue an emergency land decree. Mantetsu then presents itself as the compliant operator attacked by an impulsive government.</p>"},
      {id:"intervention",title:"The unequal compromise",html:"<p>Tokyo orders withdrawal of the visible escalation and directs Mantetsu to concede something additional. Manchukuo obtains a portion of its jurisdictional demand while the company retains ownership, dispatch, finance, standards, procurement, and strategic appointments.</p>"},
      {id:"learning",title:"The learned political method",html:"<p>Mantetsu preserves records, obtains ministry opinions in advance, prepares quantitative arguments, briefs friendly media, and makes the first token concession. Other corporate houses adopt the method throughout the Sphere.</p>"},
      {id:"legacy",title:"The first corporate dystopia",html:"<p>Manchukuoan and Japanese writers depict a company that never formally disobeys, never governs, and never loses. Its power lies in causing the sovereign state to appear emotional while corporate choices appear technical and inevitable.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"manchukuoan-industrial-sovereignty.html",kicker:"National question",label:"Manchukuoan Industrial Sovereignty"},{href:"japanese-cyberpunk.html",kicker:"Cultural legacy",label:"Japanese Cyberpunk"}],
    facts:[["Principal parties","Manchukuo and Mantetsu"],["Main period","1970s–1990s"],["Disputed issues","Tax, police, promotion, land, records, utilities, and ownership"],["Mantetsu method","Narrow compliance and technical pressure"],["Manchukuoan weakness","Visible political escalation"],["Arbiter","Japanese ministries and cabinet"],["Typical settlement","Jurisdictional concession without control transfer"],["Long-term effect","Model for corporate political self-defense"]]
  }),

  "manchukuoan-industrial-sovereignty": geacpsCorporateArticle({
    title:"Manchukuoan Industrial Sovereignty",category:"Economic history",eyebrow:"Manchukuo · industry · national authority",infoboxKicker:"Associated-state sovereignty problem",
    flag:{src:"assets/diagrams/corporate-host-bargain.svg",alt:"Industrial chain separating Manchukuoan territory and workers from Japanese capital and strategic command",caption:"Manchukuo possesses industrial mass but does not control the full chain that makes that mass sovereign"},
    lead:"Manchukuoan industrial sovereignty is the unresolved question of whether the northern Sphere's largest associated industrial state controls its own productive system. Manchukuo possesses heavy plants, skilled citizens, resources, ministries, armed forces, and a national court, but Japanese firms retain decisive command of capital, transport, patents, advanced equipment, and export access.",
    canon:"Manchukuo's industrial role, titular-national political project, Japanese ownership, economic-nationalist demands, partial jurisdictional victories, and continuing strategic dependence are established. Output totals, company shares, national champions, and post-2000 reforms remain open.",
    sections:[
      {id:"arsenal",title:"The northern arsenal",html:"<p>Manchukuo produces steel, chemicals, railway equipment, vehicles, engines, arms, mining machinery, and intermediate goods. Its scale exceeds that of most associates and gives its ministers a plausible claim to major-power status inside the Sphere.</p>"},
      {id:"chains",title:"Industry as a chain",html:"<p>The visible factory is only one link. Japanese banks fund it, insurers cover it, Mantetsu supplies and dispatches it, Japanese houses provide machine tools and licenses, and imperial contracts determine its market. Control of the chain matters more than the flag above the gate.</p>"},
      {id:"state",title:"The Manchukuoan state claim",html:"<p>The court and ministries argue that a permanent Manchurian nation cannot remain a tenant inside its own industrial cities. National dignity requires taxes, police authority, trained citizens, access to records, local procurement, and some capacity to set investment priorities.</p>"},
      {id:"japanese",title:"The Japanese answer",html:"<p>Japanese firms answer that they supplied capital, engineering culture, risk, management, standards, and markets. Local operation proves successful development; it does not create a right to confiscate the institutions that made development possible.</p>"},
      {id:"cadres",title:"The rise of national technical cadres",html:"<p>Manchukuoan engineers and managers increasingly operate complexes and regional systems. Their advancement strengthens the state while revealing the ceiling: they may direct production but not the allocation of group capital or the strategic decisions of the Japanese parent.</p>"},
      {id:"redundancy",title:"The redundancy program",html:"<p>Ministries seek national spare reserves, copied operational records, domestic suppliers, public technical schools, emergency procedures, and state firms able to continue essential work through a temporary corporate dispute.</p>"},
      {id:"limits",title:"The protected ceiling",html:"<p>Tokyo permits resilience but blocks a wholly independent strategic system. Advanced designs, sensitive armaments, continental dispatch, foreign finance, and controlling ownership remain inside institutions Japan can command.</p>"},
      {id:"meaning",title:"Powerful and incomplete",html:"<p>Manchukuo is neither a sham state nor an equal industrial sovereign. Its factories make it consequential; the corporate chains governing them make it dependent. That contradiction defines its mature nationalism.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"mantetsu-manchukuo-disputes.html",kicker:"Political conflict",label:"Mantetsu–Manchukuo Disputes"},{href:"corporate-cities-manchukuo.html",kicker:"Urban system",label:"Corporate Cities in Manchukuo"}],
    facts:[["State","Manchukuo"],["Principal sectors","Steel, chemicals, rail, vehicles, engines, arms, and mining machinery"],["Principal external operator","Mantetsu and Japanese corporate houses"],["National strength","Industrial mass and trained cadres"],["Strategic weakness","Foreign-controlled economic chains"],["National program","Jurisdiction, redundancy, and advancement"],["Japanese reserve","Ownership, advanced technology, and system direction"],["Status by 2000","Powerful associated industry; incomplete sovereignty"]]
  }),

  "corporate-cities-manchukuo": geacpsCorporateArticle({
    title:"Corporate Cities in Manchukuo",category:"Urban history",eyebrow:"Railway cities · industrial municipalities · Manchukuo",infoboxKicker:"Company-built urban order",
    flag:{src:"assets/diagrams/corporate-politics-geacps.svg",alt:"Diagram of a corporate city linking railway, factory, utilities, housing, schools, police, and municipal government",caption:"The company city makes corporate authority visible where transport, housing, work, and public services share one operator"},
    lead:"Corporate cities in Manchukuo are railway, mining, industrial, and settlement municipalities whose essential land, employment, utilities, transport, housing, schools, and commercial services were built or operated by Japanese firms. They become the most contested sites in the struggle between national sovereignty and corporate continuity.",
    canon:"The importance of chartered corporate cities, their service systems, mixed populations, Japanese institutional privileges, 1970s–1980s municipal reforms, and continued corporate influence are established. City list, charters, boundaries, populations, and local political histories remain open.",
    sections:[
      {id:"origins",title:"From concession to city",html:"<p>A station, mine, mill, arsenal, or power site draws banks, depots, housing, clinics, shops, schools, police arrangements, and roads. The operating company becomes a practical municipal government before national administration possesses comparable capacity.</p>"},
      {id:"land",title:"The corporate land system",html:"<p>Company title may derive from concession, grant, purchase, foreclosure, redevelopment, or former military property. Streets, utilities, worker housing, and industrial buffers blur the boundary between private estate and public city.</p>"},
      {id:"population",title:"A layered urban population",html:"<p>Japanese treaty residents, Manchu and Han citizens, Korean Japanese, Russians, Mongols, and other workers share the city under different citizenship and institutional systems. Company rank, nationality, and housing class often reinforce one another.</p>"},
      {id:"services",title:"The competent corporate municipality",html:"<p>Corporate water, power, transport, hospitals, schools, fire services, stores, and maintenance can outperform poorer national municipalities. This practical competence supplies the strongest argument against abrupt transfer.</p>"},
      {id:"grievance",title:"The national grievance",html:"<p>Ministers and mayors object that a private Japanese board can decide road access, housing, promotion, freight, utilities, and industrial land inside a sovereign state. Tax exemptions and separate policing make some districts appear extraterritorial.</p>"},
      {id:"reform",title:"Municipalization",html:"<p>Reforms extend national police access, taxes, labor codes, inspection, public roads, language requirements, and elected or appointed municipal bodies. Companies retain industrial property, service contracts, and strategic facilities.</p>"},
      {id:"politics",title:"Company-town politics",html:"<p>Unions, merchant groups, settler associations, professional societies, municipal candidates, and national parties all depend to varying degrees upon corporate employment and sponsorship. Open civic institutions develop inside an economically narrow environment.</p>"},
      {id:"legacy",title:"The city that cannot choose its founder",html:"<p>By 2000 the corporate city is legally more Manchukuoan and socially more rooted than before. It remains dependent upon the company whose archives, maintenance, jobs, and credit make the municipality viable.</p>"}
    ],
    related:[...geacpsCorporateRelated,{href:"japanese-settlement-manchukuo.html",kicker:"Settler society",label:"Japanese Settlement in Manchukuo"},{href:"manchukuoan-industrial-sovereignty.html",kicker:"National conflict",label:"Manchukuoan Industrial Sovereignty"}],
    facts:[["Principal locations","Rail, mining, industrial, and military corridors"],["Founding operators","Mantetsu and Japanese corporate houses"],["Core systems","Employment, land, housing, utilities, and transport"],["Population","Multiethnic; legally differentiated"],["Reform period","1970s–1980s"],["National gains","Tax, police, inspection, language, and public access"],["Corporate reserve","Industrial property and essential-service contracts"],["Status by 2000","National municipality with persistent corporate dominance"]]
  })
});

